                jsonl = p
                break
        if not jsonl:
            continue
        try:
            text = jsonl.read_text(errors="replace")
        except Exception:
            continue
        for m in re.finditer(r'"sessionID"\s*:\s*"ses_([^"]+)"', text):
            child = "ses_" + m.group(1)
            if child == sid:
                continue
            sub_line = re.search(
                r'"type"\s*:\s*"session\.sub_created"'  + 
                r'[^}]*' + rf'"sessionID"\s*:\s*"{child}"',
                text,
            )
            if not sub_line:
                sub_line = re.search(
                    rf'"sessionID"\s*:\s*"{child}"' +
                    r'[^}]*' + r'"type"\s*:\s*"session\.sub_created"',
                    text,
                )
            if sub_line:
                parent_map[child] = sid
    children: dict[str, set[str]] = {}
    for child, parent in parent_map.items():
        children.setdefault(parent, set()).add(child)
    return children

